        test_vectors[0] = {2'b00, 1'b0, 2'b00, 1'b0}; // State A, in=0 -> A, 0
        test_vectors[1] = {2'b00, 1'b1, 2'b01, 1'b0}; // State A, in=1 -> B, 0
        test_vectors[2] = {2'b01, 1'b0, 2'b10, 1'b0}; // State B, in=0 -> C, 0
        test_vectors[3] = {2'b01, 1'b1, 2'b01, 1'b0}; // State B, in=1 -> B, 0
        test_vectors[4] = {2'b10, 1'b0, 2'b00, 1'b0}; // State C, in=0 -> A, 0
        test_vectors[5] = {2'b10, 1'b1, 2'b11, 1'b0}; // State C, in=1 -> D, 0
        test_vectors[6] = {2'b11, 1'b0, 2'b10, 1'b1}; // State D, in=0 -> C, 1
        test_vectors[7] = {2'b11, 1'b1, 2'b01, 1'b1}; // State D, in=1 -> B, 1
        test_vectors[8] = {2'b00, 1'bx, 2'b00, 1'b0}; // State A, in=x -> A, 0
        test_vectors[9] = {2'b11, 1'bx, 2'b01, 1'b1}; // State D, in=x -> B, 1

        // Apply test vectors
        for (integer i = 0; i < 10; i = i + 1) begin
            {state, in} = test_vectors[i][5:0];
            #10; // Wait for the output to stabilize

            // Check outputs
            if (next_state !== test_vectors[i][3:2]) begin
                $display("Error: Test %0d failed. Expected next_state: %b, got: %b", i, test_vectors[i][3:2], next_state);
                errors = errors + 1;
            end
            if (out !== test_vectors[i][1]) begin
                $display("Error: Test %0d failed. Expected out: %b, got: %b", i, test_vectors[i][1], out);
                errors = errors + 1;
            end
        end

        // Final result
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end
endmodule
